INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'ambition', 'n.', '/æmˈbɪʃ(ə)n/', '追求;理想;志向', 'Her ambition is to design robots that will help people in the future.', '她的理想是设计未来能帮助人们的机器人。', 'Facing the Future', 1, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a strong ambition', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'ambitious', 'adj.', '/æmˈbɪʃəs/', '有雄心的;有抱负的;有野心的', 'The young engineer is ambitious and dreams of changing the future of travel.', '这位年轻工程师很有抱负,梦想改变未来的出行方式。', 'Facing the Future', 2, 0, 'senior', 'wordlist', 'elective4', 'U1', 'an ambitious plan', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'correspondent', 'n.', '/ˌkɒrɪˈspɒndənt/', '通讯员;(报道某地或某领域的)记者', 'He worked as a foreign correspondent before he became a famous writer.', '他成为著名作家之前曾做过驻外记者。', 'Facing the Future', 3, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a foreign correspondent', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'detective', 'n.', '/dɪˈtektɪv/', '侦探', 'Sherlock Holmes is the most famous detective in English fiction.', '夏洛克·福尔摩斯是英语小说中最著名的侦探。', 'Facing the Future', 4, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a famous detective', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'ultimately', 'adv.', '/ˈʌltɪmɪtli/', '最后;最终;归根结底', 'Both writers ultimately succeeded, though their paths to the future were very different.', '两位作家最终都成功了,尽管他们通往未来的道路截然不同。', 'Facing the Future', 5, 0, 'senior', 'wordlist', 'elective4', 'U1', 'ultimately succeed', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'participation', 'n.', '/pɑːˌtɪsɪˈpeɪʃ(ə)n/', '参加;参与', 'Active participation in clubs helps students prepare for their future careers.', '积极参加社团有助于学生为未来的职业做准备。', 'Facing the Future', 6, 0, 'senior', 'wordlist', 'elective4', 'U1', 'active participation', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'complex', 'adj.', '/ˈkɒmpleks/', '复杂的;难懂的', 'Machines are good at simple tasks, but humans still handle complex thinking better.', '机器擅长简单任务,但人类仍更善于处理复杂的思考。', 'Facing the Future', 7, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a complex problem', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'commercial', 'n.', '/kəˈmɜːʃ(ə)l/', '(电视或电台的)商业广告', 'The famous poem has even been used in a television commercial.', '这首著名的诗甚至被用在了一则电视广告里。', 'Facing the Future', 8, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a television commercial', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'symbolize', 'v.', '/ˈsɪmbəlaɪz/', '象征;代表', 'In the poem, the two roads symbolize the choices we face about our future.', '在诗中,两条路象征着我们面对未来时要做的抉择。', 'Facing the Future', 9, 0, 'senior', 'wordlist', 'elective4', 'U1', 'symbolize a choice', '英式拼 symbolise', 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'alternative', 'n.', '/ɔːlˈtɜːnətɪv/', '可供选择的事物;替代选择', 'Life offers us many alternatives, and each one leads to a different future.', '生活给我们提供许多选择,而每一个选择都通向不同的未来。', 'Facing the Future', 10, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a better alternative', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'arise', 'v.', '/əˈraɪz/', '出现;产生;(由……)引起', 'When new problems arise, we should face them with courage rather than fear.', '当新问题出现时,我们应该勇敢而非恐惧地面对。', 'Facing the Future', 11, 0, 'senior', 'wordlist', 'elective4', 'U1', 'problems arise', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'circumstance', 'n.', '/ˈsɜːkəmstæns/', '情况;情形;环境', 'In most circumstances, once we make a decision, there is no going back.', '在大多数情况下,一旦我们做出决定,就没有回头路了。', 'Facing the Future', 12, 0, 'senior', 'wordlist', 'elective4', 'U1', 'in most circumstances', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'mixture', 'n.', '/ˈmɪkstʃə/', '混合;混合体', 'The road ahead is a mixture of choice and chance.', '前方的道路是选择与机遇的混合体。', 'Facing the Future', 13, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a mixture of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'affection', 'n.', '/əˈfekʃ(ə)n/', '喜爱;钟爱;情感', 'A rose can symbolize love and affection in a poem.', '在诗中,玫瑰可以象征爱与深情。', 'Facing the Future', 14, 0, 'senior', 'wordlist', 'elective4', 'U1', 'deep affection', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'qualified', 'adj.', '/ˈkwɒlɪfaɪd/', '合格的;胜任的;有资格的', 'After years of training, she felt fully qualified for the new job.', '经过多年培训,她觉得自己完全能胜任这份新工作。', 'Facing the Future', 15, 0, 'senior', 'wordlist', 'elective4', 'U1', 'well qualified', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'fluency', 'n.', '/ˈfluːənsi/', '(语言的)熟练;流利', 'Fluency in English will open many doors in your future career.', '英语流利会为你未来的职业打开许多扇门。', 'Facing the Future', 16, 0, 'senior', 'wordlist', 'elective4', 'U1', 'fluency in English', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'sincerely', 'adv.', '/sɪnˈsɪəli/', '由衷地;真诚地', 'I sincerely hope to gain some experience in this field.', '我真诚地希望在这个领域获得一些经验。', 'Facing the Future', 17, 0, 'senior', 'wordlist', 'elective4', 'U1', 'thank sincerely', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'yours sincerely', 'phr.', '/jɔːz sɪnˈsɪəli/', '谨上;敬上(用于以姓名开头的正式信件结尾)', 'He ended his application letter with the words "Yours sincerely".', '他用“谨上”一词结束了他的求职信。', 'Facing the Future', 18, 0, 'senior', 'wordlist', 'elective4', 'U1', 'Yours sincerely, Josie', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'refreshments', 'n.', '/rɪˈfreʃmənts/', '茶点;点心和饮料', 'The office assistant has to prepare refreshments before each meeting.', '办公室助理要在每次会议前准备好茶点。', 'Facing the Future', 19, 0, 'senior', 'wordlist', 'elective4', 'U1', 'prepare refreshments', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'shift', 'n.', '/ʃɪft/', '(轮班制中的)当班时间;轮班', 'The part-time job means working five days a week on the morning shift.', '这份兼职意味着每周上五天早班。', 'Facing the Future', 20, 0, 'senior', 'wordlist', 'elective4', 'U1', 'the morning shift', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'boyhood', 'n.', '/ˈbɔɪhʊd/', '(男性的)童年时期;少年时代', 'From early boyhood he was single-minded in his ambition to write.', '从孩提时代起,他就一心想着写作的理想。', 'Facing the Future', 21, 0, 'senior', 'wordlist', 'elective4', 'U1', 'from early boyhood', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'trainee', 'n.', '/ˌtreɪˈniː/', '接受培训的人;实习生', 'He joined a local newspaper as a trainee reporter after leaving school.', '离校后他进入一家本地报社当实习记者。', 'Facing the Future', 22, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a trainee reporter', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bullfighting', 'n.', '/ˈbʊlfaɪtɪŋ/', '斗牛', 'He wrote stories based on his own experiences of bullfighting and deep-sea fishing.', '他根据自己斗牛和深海捕鱼的经历写了一些故事。', 'Facing the Future', 23, 0, 'senior', 'wordlist', 'elective4', 'U1', 'write about bullfighting', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'historical', 'adj.', '/hɪˈstɒrɪk(ə)l/', '(有关)历史的', 'Doyle longed to be remembered for his historical novels.', '多伊尔渴望因他的历史小说而被人铭记。', 'Facing the Future', 24, 0, 'senior', 'wordlist', 'elective4', 'U1', 'historical novels', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'dot', 'n.', '/dɒt/', '点;小圆点', 'You can only connect the dots of your life by looking backwards.', '你只能通过回望才能把人生的点点滴滴连起来。', 'Facing the Future', 25, 0, 'senior', 'wordlist', 'elective4', 'U1', 'connect the dots', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'backwards', 'adv.', '/ˈbækwədz/', '向后;往回', 'We understand our choices only by looking backwards, not forwards.', '我们只有向后回望、而非向前展望,才能理解自己的选择。', 'Facing the Future', 26, 0, 'senior', 'wordlist', 'elective4', 'U1', 'look backwards', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'admission', 'n.', '/ədˈmɪʃ(ə)n/', '准许进入(加入);录取', 'She had been recommended for early admission to study physics.', '她已被推荐免试录取去学物理。', 'Facing the Future', 27, 0, 'senior', 'wordlist', 'elective4', 'U1', 'early admission', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'diverge', 'v.', '/daɪˈvɜːdʒ/', '(道路等)岔开;分开', 'Two roads diverged in a wood, and the traveller had to choose one.', '树林里两条路岔开了,旅人必须选择其中一条。', 'Facing the Future', 28, 0, 'senior', 'wordlist', 'elective4', 'U1', 'roads diverge', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'undergrowth', 'n.', '/ˈʌndəɡrəʊθ/', '下层灌木丛', 'He watched one road until it bent away into the undergrowth.', '他望着一条路,直到它拐进灌木丛中消失。', 'Facing the Future', 29, 0, 'senior', 'wordlist', 'elective4', 'U1', 'bend in the undergrowth', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'numerous', 'adj.', '/ˈnjuːm(ə)rəs/', '众多的;许多的', 'The future offers young people numerous chances to grow.', '未来为年轻人提供了众多成长的机会。', 'Facing the Future', 30, 0, 'senior', 'wordlist', 'elective4', 'U1', 'numerous chances', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'thoughtful', 'adj.', '/ˈθɔːtf(ə)l/', '认真思考的;深思的;体贴的', 'The poem is loved for its thoughtful insights into human nature.', '这首诗因其对人性深思熟虑的洞察而受人喜爱。', 'Facing the Future', 31, 0, 'senior', 'wordlist', 'elective4', 'U1', 'thoughtful insights', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'dilemma', 'n.', '/dɪˈlemə/', '进退两难的境地;困境', 'The greatest dilemmas arise when we are unsure which choice is right.', '最大的困境出现在我们不确定哪个选择正确的时候。', 'Facing the Future', 32, 0, 'senior', 'wordlist', 'elective4', 'U1', 'face a dilemma', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'approach', 'v./n.', '/əˈprəʊtʃ/', '对待;处理;靠近;方法', 'How should we approach the future — shape it, or just accept it?', '我们应如何对待未来——是塑造它,还是只是接受它?', 'Facing the Future', 33, 0, 'senior', 'wordlist', 'elective4', 'U1', 'approach the future', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'guarantee', 'n./v.', '/ˌɡærənˈtiː/', '保证;担保', 'Having a plan is no guarantee that it will become reality.', '有计划并不能保证它一定会变成现实。', 'Facing the Future', 34, 0, 'senior', 'wordlist', 'elective4', 'U1', 'no guarantee', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'fortunate', 'adj.', '/ˈfɔːtʃənət/', '幸运的;好运的', 'Some people are more fortunate than others when their plans come true.', '在计划得以实现这件事上,有些人比别人更幸运。', 'Facing the Future', 35, 0, 'senior', 'wordlist', 'elective4', 'U1', 'more fortunate', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'encounter', 'v./n.', '/ɪnˈkaʊntə/', '遭遇;遇到;邂逅', 'Whatever twists and turns you might encounter, be prepared for the unexpected.', '无论你会遇到怎样的曲折,都要为意外做好准备。', 'Facing the Future', 36, 0, 'senior', 'wordlist', 'elective4', 'U1', 'encounter twists and turns', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'renowned', 'adj.', '/rɪˈnaʊnd/', '著名的;有名望的', 'The renowned innovator Steve Jobs spoke about trusting the future.', '著名的创新者史蒂夫·乔布斯谈到了要信任未来。', 'Facing the Future', 37, 0, 'senior', 'wordlist', 'elective4', 'U1', 'a renowned innovator', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'consequence', 'n.', '/ˈkɒnsɪkwəns/', '结果;后果', 'All our choices lead to specific consequences in the future.', '我们所有的选择都会在未来带来特定的结果。', 'Facing the Future', 38, 0, 'senior', 'wordlist', 'elective4', 'U1', 'lead to consequences', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'optimism', 'n.', '/ˈɒptɪmɪzəm/', '乐观;乐观主义', 'We should face our future with energy and optimism.', '我们应该以活力和乐观面对未来。', 'Facing the Future', 39, 0, 'senior', 'wordlist', 'elective4', 'U1', 'with optimism', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'take action', 'phr.', '/teɪk ˈækʃ(ə)n/', '采取行动', 'Can we take action to shape the future, or just accept whatever comes?', '我们能采取行动塑造未来,还是只能接受降临的一切?', 'Facing the Future', 40, 0, 'senior', 'wordlist', 'elective4', 'U1', 'take action to shape it', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'make up one''s mind', 'phr.', '/ˌmeɪk ʌp wʌnz ˈmaɪnd/', '做出决定;拿定主意', 'She could not make up her mind about which path to choose.', '她拿不定主意该选哪条路。', 'Facing the Future', 41, 0, 'senior', 'wordlist', 'elective4', 'U1', 'make up your mind', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'pass up', 'phr.', '/ˌpɑːs ˈʌp/', '放过;错过(机会)', 'It would be a pity to pass up such a wonderful opportunity.', '错过这么好的机会就太可惜了。', 'Facing the Future', 42, 0, 'senior', 'wordlist', 'elective4', 'U1', 'pass up an opportunity', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'have second thoughts', 'phr.', '/həv ˌsekənd ˈθɔːts/', '(对原决定)犹豫;产生怀疑', 'After saying yes, he began to have second thoughts about the plan.', '答应之后,他开始对这个计划产生犹豫。', 'Facing the Future', 43, 0, 'senior', 'wordlist', 'elective4', 'U1', 'have second thoughts', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'put off', 'phr.', '/ˌpʊt ˈɒf/', '推迟;使延期', 'Can you put off making the decision until you have spoken to your teacher?', '你能不能等和老师谈过之后再做决定?', 'Facing the Future', 44, 0, 'senior', 'wordlist', 'elective4', 'U1', 'put off a decision', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'weigh up', 'phr.', '/ˌweɪ ˈʌp/', '仔细考虑;权衡', 'Let''s weigh up the options carefully before we come to a decision.', '在做决定之前,让我们仔细权衡各种选择。', 'Facing the Future', 45, 0, 'senior', 'wordlist', 'elective4', 'U1', 'weigh up the options', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'reject out of hand', 'phr.', '/rɪˌdʒekt aʊt əv ˈhænd/', '坚决拒绝;彻底否决', 'I wouldn''t reject any chance out of hand before thinking it over.', '在仔细考虑之前,我不会一口回绝任何机会。', 'Facing the Future', 46, 0, 'senior', 'wordlist', 'elective4', 'U1', 'reject it out of hand', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe4u1.01', '①现在时态(一般/进行/完成/完成进行,靠标志词判断)', 'A2', 12, '外研社版选择性必修第四册 U1 — every day/usually/as a rule 等→一般现在;now/at the moment/Look!→现在进行;already/so far/up to now/this is the first time→现在完成;all morning/for ... and still→现在完成进行。', 1, 'elective4', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe4u1.02', '②过去时态(一般/进行/完成/过去将来,靠标志词判断)', 'A2', 12, '外研社版选择性必修第四册 U1 — in 1899/ago/after leaving→一般过去;while/at eight last night→过去进行;by the time/before/by 2010→过去完成;promised/never imagined that ... would→过去将来。', 2, 'elective4', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe4u1.03', '③将来表达(will/be going to/现在进行表将来/将来进行/将来完成)', 'A2', 12, '外研社版选择性必修第四册 U1 — I think ... probably→will;already decided/evidence→be going to;tomorrow at three(固定安排)→现在进行表将来;at this time next year→将来进行;by + 将来时间→将来完成。', 3, 'elective4', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'Every spring, our school ____ a science fair where students show their inventions.', 'holds', 'is holding', 'has held', 'has been holding', 'A', 'Every spring 表习惯性反复发生,用一般现在时。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'Look! The new delivery robot ____ along the pavement towards the school gate.', 'moves', 'is moving', 'has moved', 'moved', 'B', 'Look! 提示此刻正在进行的动作,用现在进行时。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'So far, researchers ____ three safe new ways to store solar power.', 'found', 'are finding', 'have found', 'find', 'C', 'So far 表到目前为止的成果,用现在完成时。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'My brother ____ on his coding project all morning, and he still hasn''t taken a break.', 'has worked', 'is working', 'works', 'has been working', 'D', 'all morning + still 强调动作从过去持续到现在且仍在继续,用现在完成进行时。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'As a rule, our class ____ a coding lesson on Friday afternoons.', 'has', 'is having', 'has had', 'has been having', 'A', 'As a rule + on Friday afternoons 表惯例,用一般现在时。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'At the moment, engineers ____ a bridge that cars will one day cross without drivers.', 'design', 'are designing', 'have designed', 'designed', 'B', 'At the moment 表此刻正在进行,用现在进行时。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'Up to now, the company ____ over a thousand smart watches this year.', 'sold', 'is selling', 'has sold', 'sells', 'C', 'Up to now + this year 表到目前的累计结果,用现在完成时。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'She ____ for the future job market for two years, and she is still studying hard.', 'has prepared', 'prepares', 'is preparing', 'has been preparing', 'D', 'for two years + still 强调持续至今且未停止,用现在完成进行时。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'According to the timetable, the high-speed train to the tech park ____ at seven every morning.', 'leaves', 'is leaving', 'has left', 'has been leaving', 'A', '时刻表 + every morning 表固定安排,用一般现在时。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'Right now, the city ____ thousands of charging points for electric cars.', 'builds', 'is building', 'has built', 'built', 'B', 'Right now 表此刻正在进行,用现在进行时。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'This is the first time I ____ a self-driving car move on a real road.', 'saw', 'see', 'have seen', 'am seeing', 'C', 'This is the first time + that 从句用现在完成时。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'The programmers ____ the new app since this morning, and they don''t plan to stop yet.', 'have tested', 'test', 'are testing', 'have been testing', 'D', 'since this morning + don''t plan to stop 强调持续进行,用现在完成进行时。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'My grandfather ____ his tablet twice a day to read the news about new technology.', 'uses', 'is using', 'has used', 'has been using', 'A', 'twice a day 表习惯频率,用一般现在时。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'At present, our company ____ more young AI engineers than ever before.', 'hires', 'is hiring', 'has hired', 'hired', 'B', 'At present + more ... than ever 表此阶段不断变化的情形,用现在进行时。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'So far this term, our school ____ every classroom with a smart screen.', 'fitted', 'fits', 'has fitted', 'is fitting', 'C', 'So far this term 表到目前为止已完成,用现在完成时。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'My sister ____ about her future career all day, and she still can''t decide.', 'has thought', 'thinks', 'is thinking', 'has been thinking', 'D', 'all day + still 强调持续动作,用现在完成进行时。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'Everyone knows that clean energy ____ an important part in modern life.', 'plays', 'is playing', 'has played', 'has been playing', 'A', 'knows that 引出的普遍事实,用一般现在时。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'Listen! The science teacher ____ about how robots will change our jobs.', 'talks', 'is talking', 'has talked', 'talked', 'B', 'Listen! 提示此刻正在进行,用现在进行时。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'I can''t join the coding club yet, because I ____ my homework so far.', 'didn''t finish', 'don''t finish', 'haven''t finished', 'am not finishing', 'C', 'yet + so far 表到现在为止尚未完成,用现在完成时(否定)。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.01'), 'Our teacher ____ us about future careers all week, and the lessons continue tomorrow.', 'has told', 'tells', 'is telling', 'has been telling', 'D', 'all week + continue tomorrow 强调持续进行,用现在完成进行时。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'Ernest Hemingway ____ a local newspaper as a young reporter after leaving high school.', 'joined', 'was joining', 'had joined', 'would join', 'A', 'after leaving high school 表过去某时点完成的动作,用一般过去时。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'While Doyle ____ for patients in his clinic, he wrote some of his first detective stories.', 'waited', 'was waiting', 'had waited', 'would wait', 'B', 'While 引导的背景动作与过去另一动作同时发生,用过去进行时。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'By the time the results came out, she ____ her future major.', 'chose', 'was choosing', 'had chosen', 'would choose', 'C', 'By the time + 过去动作,表示更早发生的动作,用过去完成时。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'As a boy, Doyle promised himself that one day he ____ a famous writer.', 'will become', 'has become', 'becomes', 'would become', 'D', 'promised 是过去时,从句表从过去看的将来,用过去将来时 would。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'Arthur Conan Doyle ____ in Scotland in 1859.', 'was born', 'was being born', 'had been born', 'would be born', 'A', 'in 1859 表过去明确时间,出生用一般过去时 was born。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'This time last year, I ____ about which university to apply to.', 'thought', 'was still thinking', 'had thought', 'would think', 'B', 'This time last year 表过去某时刻正在进行,用过去进行时。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'Before the smartphone appeared, few people ____ that a phone could replace a computer.', 'imagined', 'were imagining', 'had imagined', 'would imagine', 'C', 'Before + 过去动作,表更早的过去,用过去完成时。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'She told me on Monday that she ____ to study robotics the following year.', 'is going', 'has gone', 'went', 'was going', 'D', 'told 是过去时,was going to 表从过去看的打算(过去将来)。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'The first home computer ____ on sale more than forty years ago.', 'went', 'was going', 'had gone', 'would go', 'A', 'ago 表过去明确时间,用一般过去时。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'I ____ a documentary about future cities when the power suddenly went off.', 'watched', 'was watching', 'had watched', 'would watch', 'B', '过去某动作进行中被 when 引导的短暂动作打断,用过去进行时。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'After she ____ all the advantages and disadvantages, she finally made up her mind.', 'weighed', 'was weighing', 'had weighed', 'would weigh', 'C', 'After + 先发生的动作,后接 finally made,用过去完成时表先后。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'Nobody guessed that the small start-up ____ a giant company one day.', 'will become', 'became', 'had become', 'would become', 'D', 'guessed 是过去时,从句表从过去看的将来,用过去将来时 would。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'In his early years, Doyle ____ as a doctor in a small town.', 'worked', 'works', 'had worked', 'would work', 'A', 'In his early years 表过去一段时间内的事实,用一般过去时。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'At eight o''clock last night, my team ____ our plan for the future-tech show.', 'discussed', 'was discussing', 'had discussed', 'would discuss', 'B', 'At eight o''clock last night 表过去某时刻正在进行,用过去进行时。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'When I arrived at the lab, the others ____ the experiment, so I had missed it.', 'finished', 'were finishing', 'had finished', 'would finish', 'C', '动作发生在 arrived 之前(so I had missed it),用过去完成时。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'As a child, Steve Jobs never imagined that his ideas ____ the whole world.', 'will change', 'changed', 'have changed', 'would change', 'D', 'imagined 是过去时,从句表从过去看的将来,用过去将来时 would。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'The teacher ____ us a questionnaire about our goals at the start of last term.', 'gave', 'was giving', 'had given', 'would give', 'A', 'at the start of last term 表过去明确时间,用一般过去时。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'While the robots ____ the heavy boxes, the workers checked the software.', 'carried', 'were carrying', 'had carried', 'would carry', 'B', 'While 引导的动作与另一过去动作同时发生,用过去进行时。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'By 2010, smartphones ____ the way millions of people lived and worked.', 'changed', 'were changing', 'had changed', 'would change', 'C', 'By 2010 表到过去某时间为止已完成,用过去完成时。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.02'), 'When she left school, she had no idea what job she ____ in ten years'' time.', 'will do', 'did', 'has done', 'would do', 'D', '主句过去时,had no idea what ... 表从过去看的将来,用过去将来时 would。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'This time next year, we ____ in our own future-tech lab.', 'will be working', 'work', 'worked', 'have worked', 'A', 'This time next year 表将来某时刻正在进行,用将来进行时。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'I''ve already decided: I ____ artificial intelligence at university next year.', 'studied', 'am going to study', 'have studied', 'was studying', 'B', 'already decided + next year 表事先定好的打算,用 be going to。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'I can''t meet you on Friday — I ____ a robotics workshop that afternoon.', 'attend', 'attended', 'am attending', 'have attended', 'C', 'on Friday + that afternoon 表已定好的安排,用现在进行时表将来。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'By the time you come back next month, our team ____ the new electric car.', 'will finish', 'finished', 'has finished', 'will have finished', 'D', 'By the time + 将来动作,表在那之前完成,用将来完成时。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'I think robots ____ many boring jobs for us in the future.', 'will do', 'are doing', 'did', 'have done', 'A', 'I think ... in the future 表对将来的预测,用 will。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'Don''t call me at nine tomorrow — I ____ my final coding exam at that exact moment.', 'will take', 'will be taking', 'take', 'took', 'B', 'at that exact moment(将来某时刻)动作正在进行,用将来进行时。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'Look how fast the battery is dropping — the robot ____ very soon.', 'stopped', 'has stopped', 'is going to stop', 'was stopping', 'C', '由眼前迹象推断即将发生,用 be going to。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'Scientists believe that by 2050 humans ____ a base on Mars.', 'will build', 'built', 'are building', 'will have built', 'D', 'by 2050(将来时间点)之前完成,用将来完成时。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'I ____ my future career plan to the class tomorrow at ten.', 'am presenting', 'present', 'presented', 'have presented', 'A', 'tomorrow at ten 表已安排好的活动,用现在进行时表将来。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'Don''t worry about the broken sensor — I ____ it for you right now.', 'am fixing', 'will fix', 'fixed', 'have fixed', 'B', 'right now 提出当场临时决定/主动帮忙,用 will。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'This time next week, we ____ our new app to investors in Shanghai.', 'present', 'will present', 'will be presenting', 'have presented', 'C', 'This time next week 表将来某时刻正在进行,用将来进行时。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'By the end of this course, you ____ how to build a simple robot.', 'will learn', 'learned', 'are learning', 'will have learned', 'D', 'By the end of this course(将来时间)之前完成,用将来完成时。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'She has made up her mind — she ____ a coding club at her school next term.', 'is going to start', 'started', 'has started', 'was starting', 'A', 'made up her mind + next term 表已定的打算,用 be going to。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'I''m sure clean energy ____ much cheaper in the coming years.', 'becomes', 'will become', 'became', 'has become', 'B', 'I''m sure ... in the coming years 表对将来的预测,用 will。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'I''m busy this weekend — I ____ my grandparents to see their new smart home on Saturday.', 'visit', 'visited', 'am visiting', 'have visited', 'C', 'this weekend + on Saturday 表已安排好的活动,用现在进行时表将来。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'Don''t expect a reply in the afternoon; I ____ in the future-skills seminar all day tomorrow.', 'will sit', 'sit', 'sat', 'will be sitting', 'D', 'all day tomorrow 表将来一整段时间内持续进行,用将来进行时。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'By the time you finish reading this article, scientists ____ another new gadget.', 'will have invented', 'will invent', 'invented', 'invent', 'A', 'By the time + 将来动作,表在那之前完成,用将来完成时。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'If the old laptop is too slow, we ____ a faster one for the lab.', 'bought', 'will buy', 'are buying', 'have bought', 'B', 'If 引导的条件状语从句,主句表将来的决定,用 will。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'Why are you carrying those wires and chips? — I ____ my own smart speaker this afternoon.', 'built', 'have built', 'am going to build', 'was building', 'C', '由前面准备好的材料看出事先的打算,用 be going to。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U1' AND code='fe4u1.03'), 'At this time next year, many of us ____ at university, far away from home.', 'study', 'studied', 'will study', 'will be studying', 'D', 'At this time next year 表将来某时刻正在进行,用将来进行时。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Two Writers, Two Roads', 'Two famous writers, born about forty years apart, show how differently a life can unfold. Ernest Hemingway knew from his early years that he wanted to write. After school he took a job as a young reporter, and his unusual experiences in Europe and Cuba later fed his novels. One book about an old fisherman and a giant fish brought him a major prize, and in the end he won an even greater award for literature. Arthur Conan Doyle followed another road. He first earned his living as a doctor, yet he dreamed of writing serious historical novels. Strangely, it was his detective stories about Sherlock Holmes that made him famous, not the books he cared about most. Readers loved Holmes so much that Doyle was forced to keep the character alive. Though both men reached success, their paths were not the same, and neither future turned out exactly as they had planned.', '记叙·两位作家不同的人生道路', 153, '[{"q":"What does the passage suggest about the two writers'' careers?","answer":"A","options":["Their lives developed in very different ways.","They both started out as doctors.","They wrote exactly the same kind of books.","Neither of them ever became well known."],"explanation":"首句 ''how differently a life can unfold'' 及全文对比的转述。"},{"q":"Why was Doyle probably not fully satisfied with his fame?","answer":"B","options":["He disliked earning any money from writing.","He became known for stories he valued less than his historical novels.","He had never managed to sell a single book.","He really wished to go back to being a doctor."],"explanation":"原文说他因侦探故事出名,而非他最在意的历史小说,可推知他并不完全满意。"},{"q":"What lesson can readers draw from the two authors?","answer":"A","options":["The future may not match our plans, even after hard work.","Talent always guarantees an easy and smooth life.","Writing is the only path that leads to success.","Plans are useless and should always be avoided."],"explanation":"末句 ''neither future turned out exactly as they had planned'' 的概括。"}]'::jsonb, '[{"word":"correspondent","cn":"记者"},{"word":"detective","cn":"侦探"},{"word":"historical","cn":"历史的"}]'::jsonb, 2, 'elective4', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Jobs of the Future', 'What will we be doing in ten years'' time? Nobody knows for sure, but experts can make some clever guesses. Many of today''s jobs will be done by machines, while brand-new jobs will appear that we cannot even name yet. People may work as robot teachers, space farmers or designers of clean energy systems. One thing seems certain: the future will reward those who keep learning. Skills such as creativity, teamwork and clear thinking will matter more than ever, because machines are still poor at these. Workers will also need to change jobs several times in their lives, so being flexible will be a great advantage. Rather than fearing these changes, young people should welcome them. By staying curious and brave, you can turn an uncertain future into a world full of exciting chances. The best way to guess your future, after all, is to help build it.', '说明·未来的职业', 148, '[{"q":"According to the passage, what will happen to many of today''s jobs?","answer":"B","options":["They will stay exactly the same.","Machines will take them over.","They will all disappear forever.","Nobody will be allowed to do them."],"explanation":"原文 ''done by machines'' 的转述。"},{"q":"Why will skills like creativity matter more in the future?","answer":"C","options":["They are becoming very easy to learn.","Schools have stopped teaching them.","Machines are still weak at them.","Machines can already do them perfectly."],"explanation":"原文 ''machines are still poor at these'' 的转述。"},{"q":"What attitude towards future change does the writer suggest?","answer":"D","options":["Ignoring it and hoping it goes away.","Trying to stop all new technology.","Waiting for others to decide everything.","Welcoming it rather than being afraid of it."],"explanation":"原文 ''Rather than fearing these changes ... should welcome them'' 的概括。"}]'::jsonb, '[{"word":"flexible","cn":"灵活的"},{"word":"creativity","cn":"创造力"}]'::jsonb, 2, 'elective4', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Gap Year in Cambodia', 'After finishing senior high, David chose to spend a gap year as a volunteer in a small Cambodian village. Each morning the birds woke him at dawn, and the day''s work began at once. For two months his team had been building a new roof for the local school, hard and tiring work under the hot sun. Yet David never regretted his choice for a single moment. He loved meeting the friendly villagers, who were always happy to share their simple lives with him. The year was not always comfortable, but it taught him patience, courage and respect for other people. He also grew fitter and far more independent than before. When the year ended, David felt that this adventure had changed him deeply. He returned home ready to begin his university studies, certain that the experience would help shape a wiser and kinder future for himself.', '记叙·海外间隔年', 147, '[{"q":"How did David feel about the hard work in the village?","answer":"A","options":["He never regretted his decision to be there.","He wished he had stayed at home instead.","He found it boring and meaningless.","He gave up halfway through the year."],"explanation":"原文 ''never regretted his choice for a single moment'' 的转述。"},{"q":"What did the gap year teach David?","answer":"B","options":["How to earn a great deal of money.","To be patient, brave and respectful to others.","How to avoid difficult people.","That travel is a waste of time."],"explanation":"原文 ''taught him patience, courage and respect for other people'' 的转述。"},{"q":"What did David plan to do after the year ended?","answer":"C","options":["Stay in Cambodia for good.","Look for a full-time job abroad.","Start studying at university.","Take another gap year at once."],"explanation":"原文 ''ready to begin his university studies'' 的转述。"}]'::jsonb, '[{"word":"volunteer","cn":"志愿者"},{"word":"independent","cn":"独立的"}]'::jsonb, 2, 'elective4', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Road Not Taken', 'Robert Frost''s famous poem The Road Not Taken describes a traveller who comes to two paths in a wood. He cannot walk both, so he must choose one and leave the other behind. The two roads look almost the same, which makes the choice even harder. In the end he takes the path that seems a little less used, knowing he will probably never come back to try the other. Many readers think the poem is about facing the future bravely and without regret. Others believe it is really about how we look back on our choices years later, sometimes with a quiet sigh. Both readings remind us that every decision closes some doors while opening others. We can never be completely sure that we chose well. What matters most, the poem suggests, is to accept our choices and make the very best of the road we have taken.', '赏析·《未选择的路》', 149, '[{"q":"Why is the traveller''s choice difficult?","answer":"D","options":["Both roads are clearly blocked.","He is told which road to take.","He has walked them many times.","The two paths look almost alike."],"explanation":"原文 ''The two roads look almost the same'' 的转述。"},{"q":"What do some readers think the poem is mainly about?","answer":"A","options":["Facing the future with courage.","The danger of walking in woods.","How to find the shortest road.","Why poems are hard to read."],"explanation":"原文 ''about facing the future bravely and without regret'' 的转述。"},{"q":"What does the poem suggest we should do about our choices?","answer":"B","options":["Change them as often as possible.","Accept them and make the most of them.","Refuse to make any choice at all.","Forget that we ever chose."],"explanation":"末句 ''accept our choices and make the very best of the road'' 的转述。"}]'::jsonb, '[{"word":"diverge","cn":"(路)岔开"},{"word":"symbolize","cn":"象征"}]'::jsonb, 2, 'elective4', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Part-time Jobs and the Future', 'A part-time job can be far more than a way to earn a little money. For many teenagers, it is an early step towards a mature and responsible adult life. Working in a cafe, an office or a shop teaches young people how to manage their time, deal with strangers and solve small problems on their own. These experiences build confidence and help students understand how society really works. Many countries also protect young workers with special rules. In the UK, for example, students aged fifteen and sixteen may work only a limited number of hours during term time, and they are not allowed to work very early or very late. Such laws make sure that a job never harms a student''s health or studies. Used wisely, a part-time job can prepare teenagers for the choices and challenges of their future careers, long before they ever leave school.', '议论·兼职与未来', 148, '[{"q":"What does the passage say a part-time job can teach teenagers?","answer":"C","options":["How to avoid all hard work.","How to leave school as early as possible.","How to manage time and solve problems by themselves.","How to spend money quickly."],"explanation":"原文 ''manage their time ... solve small problems on their own'' 的转述。"},{"q":"Why do many countries have special rules for young workers?","answer":"D","options":["To make them work longer hours.","To stop them from earning money.","To keep them out of all jobs.","To protect their health and studies."],"explanation":"原文 ''a job never harms a student''s health or studies'' 的转述。"},{"q":"What is the main point of the passage?","answer":"A","options":["Part-time jobs help prepare teenagers for the future.","Part-time jobs are only about earning money.","Teenagers should never take a job.","School matters far less than work."],"explanation":"末句关于为未来职业做准备的概括。"}]'::jsonb, '[{"word":"mature","cn":"成熟的"},{"word":"responsible","cn":"有责任心的"}]'::jsonb, 2, 'elective4', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Be Ready for the Unexpected', 'Life rarely follows the exact plan we draw for it. We may study hard for one career and then discover a completely different passion along the way. Both Ernest Hemingway and Arthur Conan Doyle reached success, yet their futures did not turn out as they first imagined. This is why wise people prepare not only for the goals they expect, but also for the surprises they cannot. Being ready for the unexpected does not mean giving up your dreams. It means staying flexible, learning new skills, and keeping an open mind when twists and turns appear. A sudden change can close one door but open another that is even better. So set clear goals and work towards them with energy, but hold your plans lightly. Whatever surprises the years may bring, a curious and brave heart will always find a new path forward.', '议论·为意外做准备', 143, '[{"q":"What does the passage say about life and our plans?","answer":"B","options":["Life always goes exactly as planned.","Life seldom follows our exact plan.","Plans never change once made.","Surprises should always be feared."],"explanation":"首句 ''Life rarely follows the exact plan'' 的转述。"},{"q":"What does being ready for the unexpected mean, according to the writer?","answer":"C","options":["Giving up all of your dreams.","Refusing to learn anything new.","Staying flexible and open-minded.","Never setting any goals."],"explanation":"原文 ''staying flexible, learning new skills, and keeping an open mind'' 的转述。"},{"q":"What advice does the writer give about goals?","answer":"D","options":["Ignore them and just wait.","Never tell anyone about them.","Choose them only after you are old.","Work towards them, but stay willing to change."],"explanation":"原文 ''set clear goals ... but hold your plans lightly'' 的转述。"}]'::jsonb, '[{"word":"encounter","cn":"遇到"},{"word":"flexible","cn":"灵活的"}]'::jsonb, 2, 'elective4', 'U1', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U1', 'After Senior High', 'Now that I have been at senior high for over a year, my teacher has asked us to think about the (1)____. I feel quite (2)____ about my progress so far, though there are still goals I have not (3)____ yet. My biggest (4)____ is to study computer science and one day build robots that help people. To reach it, I (5)____ to work much harder at maths and coding. I know that having a plan is no (6)____ that everything will come true, but it still gives me a clear (7)____. When I feel unsure, I try not to (8)____ up good chances too quickly. Instead, I (9)____ up the choices carefully before I (10)____ a decision. Step by step, I am getting ready for the future.', 128, 2, '[{"q":"1","answer":"A","options":["future","weather","price","corner"],"explanation":"think about the future,谈论未来。"},{"q":"2","answer":"B","options":["bored","satisfied","asleep","absent"],"explanation":"feel satisfied about my progress,对进步感到满意。"},{"q":"3","answer":"C","options":["lost","eaten","achieved","closed"],"explanation":"goals I have not achieved,尚未实现的目标。"},{"q":"4","answer":"D","options":["accident","illness","quarrel","ambition"],"explanation":"My biggest ambition is to ...,最大的理想。"},{"q":"5","answer":"A","options":["plan","refuse","dislike","avoid"],"explanation":"plan to work harder,打算更努力;后三个为否定意义,与上下文矛盾。"},{"q":"6","answer":"B","options":["question","guarantee","surprise","mistake"],"explanation":"no guarantee that ...,不能保证。"},{"q":"7","answer":"C","options":["weather","price","direction","noise"],"explanation":"a clear direction,清晰的方向。"},{"q":"8","answer":"D","options":["stand","sit","walk","pass"],"explanation":"pass up good chances,错过好机会。"},{"q":"9","answer":"A","options":["weigh","throw","drop","boil"],"explanation":"weigh up the choices,权衡选择。"},{"q":"10","answer":"B","options":["take","make","do","have"],"explanation":"make a decision,固定搭配。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U1', 'How AI Will Change Jobs', 'Many people wonder how computers and robots will (1)____ the world of work. Some jobs that exist today may slowly (2)____, while completely new ones will appear. Machines are already good at boring and repeated tasks, so workers will have more time for (3)____ thinking and creative ideas. However, this change also brings a real (4)____: should we welcome the new technology or fear it? Experts say the wisest (5)____ is to keep learning new skills throughout our lives. A person who is willing to (6)____ to new tools will always be useful. We should not (7)____ up the chance to learn just because it feels hard. Instead, we ought to take (8)____ early and prepare for the future. Those who plan ahead are usually more (9)____ than those who simply wait. In the end, technology is a (10)____ of both challenge and opportunity.', 144, 2, '[{"q":"1","answer":"C","options":["close","cook","change","clean"],"explanation":"change the world of work,改变职场。"},{"q":"2","answer":"D","options":["arrive","sing","rise","disappear"],"explanation":"jobs may disappear,工作可能消失。"},{"q":"3","answer":"A","options":["complex","sleepy","silent","empty"],"explanation":"complex thinking,复杂的思考。"},{"q":"4","answer":"B","options":["holiday","dilemma","picture","song"],"explanation":"a real dilemma: ... or ...,两难。"},{"q":"5","answer":"C","options":["mistake","accident","choice","noise"],"explanation":"the wisest choice is to ...,最明智的选择。"},{"q":"6","answer":"D","options":["refuse","object","complain","adapt"],"explanation":"willing to adapt to new tools,适应新工具;后三个为否定态度。"},{"q":"7","answer":"A","options":["give","put","take","cut"],"explanation":"give up the chance,放弃机会。"},{"q":"8","answer":"B","options":["lessons","action","photos","buses"],"explanation":"take action,采取行动。"},{"q":"9","answer":"C","options":["asleep","absent","successful","empty"],"explanation":"more successful than ...,更成功。"},{"q":"10","answer":"D","options":["corner","bottle","window","mixture"],"explanation":"a mixture of challenge and opportunity,二者的混合。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U1', 'A Young Inventor', 'When Mia was still a girl, she already had a clear (1)____ to become an engineer. At school she joined every science club and never (2)____ up a chance to build something new. Her teachers said she was (3)____ and full of energy. One day she read about a robot that could help blind people cross the road, and the idea (4)____ in her mind for weeks. She decided to take (5)____ and design her own version. The work was not easy, and many problems (6)____ along the way. Sometimes she had (7)____ thoughts and wondered whether she should give up. But she always chose to (8)____ up the good and bad points and keep going. (9)____, after two years of hard work, her robot won a national prize. Mia is now sure that a strong dream, plus daily effort, can shape a bright (10)____.', 145, 2, '[{"q":"1","answer":"A","options":["ambition","accident","illness","corner"],"explanation":"a clear ambition to ...,明确的理想。"},{"q":"2","answer":"B","options":["cooked","passed","painted","closed"],"explanation":"never passed up a chance,从不错过机会。"},{"q":"3","answer":"C","options":["sleepy","silent","ambitious","lazy"],"explanation":"ambitious and full of energy,有抱负、充满活力。"},{"q":"4","answer":"D","options":["ate","sang","drove","stayed"],"explanation":"the idea stayed in her mind,这个想法停留在脑海里。"},{"q":"5","answer":"A","options":["action","photos","buses","seats"],"explanation":"take action,采取行动。"},{"q":"6","answer":"B","options":["smiled","arose","danced","cooked"],"explanation":"many problems arose,出现了许多问题。"},{"q":"7","answer":"C","options":["sweet","heavy","second","round"],"explanation":"have second thoughts,犹豫。"},{"q":"8","answer":"D","options":["throw","boil","drop","weigh"],"explanation":"weigh up the good and bad points,权衡利弊。"},{"q":"9","answer":"A","options":["Ultimately","Suddenly","Sadly","Quietly"],"explanation":"Ultimately, after two years ...,最终。"},{"q":"10","answer":"B","options":["weather","future","price","corner"],"explanation":"shape a bright future,塑造光明的未来。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U1', 'A Difficult Decision', 'Li Ling was facing a hard (1)____ about her future. She had been (2)____ for early admission to study physics at a top university, which sounded wonderful. Yet she had always wanted to become a doctor, so she felt unable to (3)____ up her mind. Her friend Jenny told her not to (4)____ up such a rare opportunity without thinking. At the same time, Jenny said it would be wrong to (5)____ the dream of medicine completely. The two girls decided to (6)____ up the advantages and disadvantages of each path. Li Ling realised that, whatever she chose, the (7)____ would shape her whole life. She did not want to act too fast and later have (8)____ thoughts. In the end she promised to (9)____ off the final choice until she had spoken to her teacher. Sometimes the wisest step is to (10)____ a little more time.', 147, 2, '[{"q":"1","answer":"C","options":["breakfast","picture","decision","song"],"explanation":"a hard decision,艰难的决定。"},{"q":"2","answer":"D","options":["cooked","painted","cleaned","recommended"],"explanation":"been recommended for admission,被推荐录取。"},{"q":"3","answer":"A","options":["make","take","give","put"],"explanation":"make up her mind,拿定主意。"},{"q":"4","answer":"B","options":["stand","pass","walk","jump"],"explanation":"pass up the opportunity,错过机会。"},{"q":"5","answer":"C","options":["enjoy","repeat","reject","collect"],"explanation":"reject the dream completely,完全放弃梦想。"},{"q":"6","answer":"D","options":["boil","throw","drop","weigh"],"explanation":"weigh up the advantages and disadvantages,权衡利弊。"},{"q":"7","answer":"A","options":["choice","weather","corner","bottle"],"explanation":"the choice would shape her life,选择决定人生。"},{"q":"8","answer":"B","options":["sweet","second","heavy","round"],"explanation":"have second thoughts,犹豫、反悔。"},{"q":"9","answer":"C","options":["take","cut","put","look"],"explanation":"put off the final choice,推迟最终选择。"},{"q":"10","answer":"D","options":["sing","cook","drive","take"],"explanation":"take a little more time,多花点时间。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U1', 'Getting Ready for an Interview', 'Last summer Richard decided to apply for a part-time (1)____ at a local youth hostel. He had always been interested in travel, so the work seemed (2)____ for him. Before the interview, he prepared carefully and tried to think of polite (3)____ to ask the manager. He knew that good people skills would make him a strong (4)____. During the meeting, he spoke with (5)____ and answered every question clearly. When the manager asked why he wanted the job, Richard explained that the (6)____ would help him grow more independent. He also said that earlier holiday jobs had made him a (7)____ and flexible person. The manager was clearly (8)____ and offered him the position. Richard learned that being well prepared can (9)____ all the difference. If you ever (10)____ a job interview, remember to stay calm and be honest.', 140, 2, '[{"q":"1","answer":"A","options":["job","song","meal","river"],"explanation":"a part-time job,兼职工作。"},{"q":"2","answer":"B","options":["asleep","perfect","empty","silent"],"explanation":"the work seemed perfect for him,非常合适。"},{"q":"3","answer":"C","options":["windows","bottles","questions","corners"],"explanation":"polite questions to ask,礼貌的问题。"},{"q":"4","answer":"D","options":["breakfast","mountain","engine","candidate"],"explanation":"a strong candidate,有力的应聘者。"},{"q":"5","answer":"A","options":["confidence","anger","hunger","fear"],"explanation":"spoke with confidence,自信地说;后三个为消极情绪。"},{"q":"6","answer":"B","options":["weather","experience","traffic","furniture"],"explanation":"the experience would help him grow,这段经历有助成长。"},{"q":"7","answer":"C","options":["sleepy","silent","confident","lazy"],"explanation":"a confident and flexible person,自信而灵活的人。"},{"q":"8","answer":"D","options":["bored","asleep","absent","impressed"],"explanation":"the manager was impressed,经理印象深刻。"},{"q":"9","answer":"A","options":["make","take","do","have"],"explanation":"make all the difference,起决定性作用。"},{"q":"10","answer":"B","options":["cook","face","paint","drive"],"explanation":"face a job interview,面对面试。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U1', 'A Gap Year Abroad', 'Dear Anna, I am writing from a small village where I am spending my gap (1)____ as a volunteer. Every morning the birds wake me at dawn, and already the work (2)____. For the past two months we have been building a new roof for the village school. Despite the hard physical work, I do not (3)____ my choice for a single moment. The local people are friendly and (4)____ to share their lives with us. This experience has been a wonderful (5)____ for my personal growth. I feel happy, free, and a little (6)____ than before, because I exercise every day. Of course, life here is not always easy, and small problems often (7)____. Yet I have learned to (8)____ each difficulty calmly and find a solution. When this year (9)____, I will surely keep learning about how other people live. I am sure this adventure will (10)____ my whole future. Yours, David', 154, 2, '[{"q":"1","answer":"C","options":["metal","glass","year","paper"],"explanation":"my gap year,间隔年。"},{"q":"2","answer":"D","options":["sleeps","sings","melts","begins"],"explanation":"already the work begins,工作就开始了。"},{"q":"3","answer":"A","options":["regret","cook","paint","borrow"],"explanation":"do not regret my choice,不后悔选择。"},{"q":"4","answer":"B","options":["asleep","willing","absent","empty"],"explanation":"willing to share,乐于分享。"},{"q":"5","answer":"C","options":["accident","illness","opportunity","quarrel"],"explanation":"a wonderful opportunity,绝佳机会。"},{"q":"6","answer":"D","options":["sadder","lazier","colder","fitter"],"explanation":"a little fitter ... because I exercise,更健康。"},{"q":"7","answer":"A","options":["arise","smile","dance","cook"],"explanation":"small problems arise,小问题出现。"},{"q":"8","answer":"B","options":["eat","face","sing","paint"],"explanation":"face each difficulty calmly,冷静面对困难。"},{"q":"9","answer":"C","options":["opens","cooks","ends","flies"],"explanation":"when this year ends,当这一年结束时。"},{"q":"10","answer":"D","options":["boil","borrow","spill","shape"],"explanation":"shape my whole future,塑造我的未来。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U1 听力·对话 Future Careers', '外研社版选择性必修第四册 U1 · dialogue', 3, 'Amy: Ben, have you decided what you want to do in the future?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U1 听力·独白 Technology and Tomorrow', '外研社版选择性必修第四册 U1 · passage', 2, 'Good morning, everyone. Today I want to talk about how technology will change our daily lives in the coming years. In the future, many cars will drive themselves, so the roads may become much safer. Doctors will use smart machines to find illnesses earlier than ever before. At home, robots will help us cook, clean and even look after older people. Of course, machines cannot do everything. We will still need kind hearts, new ideas and the courage to face an uncertain future. So keep learning, stay curious, and get ready for the exciting world ahead.', '早上好。今天我想谈谈科技将如何改变我们未来几年的日常生活:许多汽车将自动驾驶,道路可能更安全;医生将用智能机器更早发现疾病;在家里机器人会帮我们做饭、打扫,甚至照顾老人。当然机器并非万能,我们仍需善良的心、新点子,以及面对不确定未来的勇气。所以要不断学习、保持好奇,为前方精彩的世界做好准备。', 'uk_male', '[{"q":"What is the talk mainly about?","type":"choice","answer":"D","options":["How to repair an old car.","Why people enjoy cooking.","Where to take a holiday.","How technology will change daily life."]},{"q":"Why may the roads become much safer?","type":"choice","answer":"A","options":["Because many cars will drive themselves.","Because nobody will drive at all.","Because all roads will be closed.","Because cars will move very slowly."]},{"q":"How will doctors use smart machines?","type":"choice","answer":"B","options":["To build new hospitals.","To find illnesses earlier than before.","To teach children at school.","To drive patients home."]},{"q":"What will robots help us do at home?","type":"choice","answer":"C","options":["Write all our homework.","Choose our friends for us.","Cook, clean and look after older people.","Decide where we work."]},{"q":"What does the speaker say we will still need?","type":"choice","answer":"D","options":["Bigger and faster machines.","Longer working hours.","Fewer new skills.","Kind hearts, new ideas and courage."]}]'::jsonb, '[]'::jsonb, 'short', 'elective4', 'U1', 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U1 听力·对话 A Job Interview', '外研社版选择性必修第四册 U1 · dialogue', 3, 'Manager: Good afternoon, Richard. Why did you apply for this job at our youth hostel?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U1 听力·独白 Facing a Decision', '外研社版选择性必修第四册 U1 · passage', 2, 'Making an important decision can feel difficult, especially when both choices look good. Here is some simple advice. First, do not act too quickly; take time to weigh up the advantages and disadvantages of each option. Second, talk to someone you trust, such as a teacher or a parent, and listen to their ideas. Third, think about your real dream, not just what looks easy today. It is fine to have second thoughts, but try not to put off the choice forever. Once you have decided, believe in yourself and move forward with confidence. Remember, every choice helps to shape the future you want.', '做重要决定可能很难,尤其当两个选择都不错时。这里有几条简单建议:第一,别太快行动,花时间权衡每个选择的利弊;第二,找你信任的人(如老师或父母)谈谈,听听他们的看法;第三,想想你真正的梦想,而不只是今天看起来轻松的事。犹豫是正常的,但别把决定一直拖下去。一旦决定,就要相信自己、自信前行。记住,每一个选择都在塑造你想要的未来。', 'uk_female', '[{"q":"What is the speaker mainly giving?","type":"choice","answer":"B","options":["A story about a journey.","Advice on making decisions.","A weather report.","A list of jobs."]},{"q":"What should you do first, according to the speaker?","type":"choice","answer":"C","options":["Decide as fast as possible.","Forget about the problem.","Take time to weigh up each option.","Ask a stranger for money."]},{"q":"Who does the speaker suggest talking to?","type":"choice","answer":"D","options":["A person you have just met.","Nobody at all.","A famous film star.","Someone you trust, like a teacher or parent."]},{"q":"What should you think about when deciding?","type":"choice","answer":"A","options":["Your real dream, not just the easy choice.","Only what your friends like.","How to avoid all hard work.","Which choice is the cheapest."]},{"q":"What should you do once you have decided?","type":"choice","answer":"B","options":["Keep changing your mind every day.","Believe in yourself and move forward.","Tell no one about it.","Give up at the first problem."]}]'::jsonb, '[]'::jsonb, 'short', 'elective4', 'U1', 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U1 听力·对话 Planning a Gap Year', '外研社版选择性必修第四册 U1 · dialogue', 3, 'Lily: Tom, what are you going to do after you finish senior high?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U1 听力·独白 Success and the Future', '外研社版选择性必修第四册 U1 · passage', 2, 'What does a successful future really mean? For some people, success is a good job and plenty of money. For others, it is health, family, or the chance to help society. I believe success is not a fixed prize that we win only once. Instead, it is the way we keep growing and learning all our lives. We cannot fully understand our path while looking forward; we can only make sense of it by looking back. So we must trust that our efforts today will somehow shape a brighter tomorrow. Set clear goals, take action, and never be afraid to face the unknown. The future belongs to those who prepare for it with energy and optimism.', '成功的未来究竟意味着什么?对一些人来说,成功是好工作和富足的金钱;对另一些人,则是健康、家庭或帮助社会的机会。我认为成功不是只赢一次的固定奖品,而是我们一生不断成长与学习的方式。向前看时我们无法完全看懂自己的路,只有回望才能理解它。所以要相信,今天的努力终将塑造更光明的明天。设定清晰目标,采取行动,永远不要害怕面对未知。未来属于那些以活力和乐观去准备的人。', 'uk_male', '[{"q":"What question does the speaker begin with?","type":"choice","answer":"D","options":["How to become rich quickly.","Where to find a new job.","When the holiday starts.","What a successful future really means."]},{"q":"What does success mean to some people, according to the speaker?","type":"choice","answer":"A","options":["A good job and plenty of money.","A long sleep every day.","Never working again.","Living completely alone."]},{"q":"What does the speaker think success really is?","type":"choice","answer":"B","options":["A prize we win only once.","The way we keep growing and learning.","Something only the rich can have.","A matter of pure luck."]},{"q":"How can we make sense of our path?","type":"choice","answer":"C","options":["By forgetting the past.","By copying other people.","By looking back on it.","By never making plans."]},{"q":"Who does the future belong to, according to the speaker?","type":"choice","answer":"D","options":["Those who simply wait and hope.","Those who fear every change.","Those who never set any goals.","Those who prepare with energy and optimism."]}]'::jsonb, '[]'::jsonb, 'short', 'elective4', 'U1', 'fltrp');
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (12, 'Write a Part-time Job Application Letter(写一封兼职求职信)', 'Application for a Part-time Tour Guide', '假设你叫 Li Hua,你在校园网上看到一则兼职招聘:City Tours Agency 招聘周末兼职导游(part-time local tour guide)。请用英语写一封约100词的求职信,内容包括:① 说明应聘的职位及从何处得知;② 你为何适合这份工作(对家乡历史的了解、英语能力);③ 相关经历(曾为外国朋友做过城市导览);④ 礼貌结尾并留下联系方式。注意:用正式书信格式,时态使用正确(past/present/future 各得其所)。', 'Suppose you are Li Hua. You saw an advertisement on the school website: City Tours Agency wants a part-time local tour guide for weekends. Write an application letter (about 100 words) including: 1) the position and where you learnt about it; 2) why you are suitable (knowledge of your home city''s history, your English); 3) relevant experience (you once guided foreign friends around your city); 4) a polite ending with your contact information. Use a formal letter format and the correct tenses.', '["说明应聘职位与信息来源(I am writing to apply for ... as advertised on ...)","陈述个人优势:对家乡历史的了解 + 英语能力(present)","陈述相关经历(past:I once organised ...)","礼貌结尾、表达期待并留联系方式(future:I would welcome the chance to ...)"]'::jsonb, 70, 100, 'Dear Sir or Madam,
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (12, 'elective4', 'U1', '{"title":"时态综合复习·过去/现在/将来 速查","intro":"时态判断的核心是「看标志词 + 看动作与说话时间的关系」。过去/现在/将来三个时间区，各有 一般 / 进行 / 完成 / (完成进行) 四种体。先确定时间区，再确定动作是「点」「线」还是「已完成」。","table":{"headers":["时间区","一般(事实/习惯)","进行(正在/某刻)","完成(已…/对现在的影响)"],"rows":[["现在","do/does：every day, usually","am/is/are doing：now, Look!","have/has done：already, so far, just"],["过去","did：ago, in 1899, yesterday","was/were doing：while, at 8 last night","had done：by the time, before, by 2010"],["将来","will do / be going to：I think…, decided","will be doing：at this time next year","will have done：by + 将来时间"]]},"specialRules":[{"rule":"现在完成进行：all morning / for ... and still ——强调动作持续到现在且未停","mark":"He has been working all morning."},{"rule":"be going to vs will：事先打算/有迹象→be going to；当场决定/纯预测→will","mark":"I''ve decided — I''m going to … / OK, I''ll do it."},{"rule":"现在进行表将来：已定好的安排 + 将来时间状语","mark":"I''m attending a workshop tomorrow."},{"rule":"过去将来 would / was going to：从过去某点看的将来(常在 said/thought/imagined 后)","mark":"She said she would come. / He never imagined his ideas would change the world."}],"why":["同一个动词，换一个时间状语就要换时态：标志词决定时间区，动作性质(点/持续/已完成)决定体。抓住这两条，时态题基本不会错。"],"gaokaoPoints":["语篇填空 / 短文改错高频:by the time → 过去完成；at this time next year → 将来进行；by + 将来时间 → 将来完成。","be going to 与 will 的区分(已决定 vs 当场决定/预测)；现在进行表将来(已安排好的活动)。","完成时与完成进行时的取舍:重结果用完成，重''一直在做、还没停''用完成进行。"],"examVsReal":[{"exam":"By 2050 humans will have built a base on Mars.(考试用将来完成)","real":"By 2050 we''ll have a base on Mars.","note":"口语里常用更简单的 will + 短语，但考试要求 by + 将来时间 → 将来完成。"},{"exam":"I''m meeting him tomorrow at three.(现在进行表将来)","real":"I''ll meet him tomorrow. / I''m gonna meet him.","note":"口语 will / be going to / 现在进行常可互换，但有明确安排时考试偏好现在进行表将来。"}]}'::jsonb, 'fltrp');
